const expected = $("Load Eval Tickets").all().map(i => i.json);
const actual = $input.all().map(i => i.json);
const keyOf = t => (t.subject || "") + "|" + (t.body || "");

const byKey = {};
for (const a of actual) byKey[keyOf(a)] = a;

let categoryCorrect = 0;
let priorityCorrect = 0;
let humanCorrect = 0;
let humanScored = 0;
let allCorrect = 0;
const failures = [];

for (const e of expected) {
  const a = byKey[keyOf(e)];
  if (!a) {
    failures.push({ case_id: e.case_id, problem: "no result returned" });
    continue;
  }
  const catOk = a.category === e.expected_category;
  const priOk = a.priority === e.expected_priority;
  const scoreHuman = e.expected_needs_human !== null;
  const humOk = !scoreHuman || a.needs_human === e.expected_needs_human;
  if (catOk) categoryCorrect++;
  if (priOk) priorityCorrect++;
  if (scoreHuman) {
    humanScored++;
    if (humOk) humanCorrect++;
  }
  if (catOk && priOk && humOk) {
    allCorrect++;
  } else {
    failures.push({
      case_id: e.case_id,
      subject: e.subject,
      expected: { category: e.expected_category, priority: e.expected_priority, needs_human: e.expected_needs_human },
      got: { category: a.category, priority: a.priority, needs_human: a.needs_human, confidence: a.confidence }
    });
  }
}

const total = expected.length;
const pct = (n, d) => (d === 0 ? 0 : Math.round((n / d) * 1000) / 10);

return [{
  json: {
    prompt_version: actual.length ? actual[0].prompt_version : "unknown",
    total,
    category_correct: categoryCorrect,
    priority_correct: priorityCorrect,
    needs_human_correct: humanCorrect,
    needs_human_scored: humanScored,
    all_correct: allCorrect,
    category_accuracy_pct: pct(categoryCorrect, total),
    priority_accuracy_pct: pct(priorityCorrect, total),
    needs_human_accuracy_pct: pct(humanCorrect, humanScored),
    all_correct_pct: pct(allCorrect, total),
    failures
  }
}];

parameters.query:
INSERT INTO eval_runs (prompt_version, total, category_correct, priority_correct, needs_human_correct, all_correct, failures)
VALUES ($1::text, $2::int, $3::int, $4::int, $5::int, $6::int, $7::jsonb)
RETURNING id, run_at;
